factoriopedia_simulation.init:
require("__core__/lualib/story")
game.simulation.camera_position = {0, 0}

for x = -8, 8, 1 do
  for y = -3, 3 do
    game.surfaces[1].set_tiles{{position = {x, y}, name = "empty-space"}}
  end
end

for x = -1, 0, 1 do
  for y = -1, 0 do
    game.surfaces[1].set_chunk_generated_status({x, y}, defines.chunk_generated_status.entities)
  end
end

local story_table =
{
  {
    {
      name = "start",
      action = function() game.surfaces[1].create_entity{name="small-metallic-asteroid", position = {0, 0}, velocity = {0, 0.011}} end
    },
    {
      condition = story_elapsed_check(7),
      action = function() story_jump_to(storage.story, "start") end
    }
  }
}
tip_story_init(story_table)

